// 复用真实开店资产写者，验证原 LE 准入和同 tick 工资补尾；人工会面/资格夹具不冒自然旅程。
#define main original_private_shop_transaction_main
#include "private_shop_transaction_test.cpp"
#undef main
#include "resident/domains/commerce/private_shop_asset_responsibilities.hpp"
namespace {
struct NoPublicAuthority:OrganizationRead {
 bool organization_exists(const StableId&)const override{return false;}bool organization_active(const StableId&)const override{return false;}
 bool institutional_obligation_allowed(const StableId&,const StableId&,const StableId&,const StableId&,Integer,Integer)const override{return false;}
 bool actor_accepts_duty(const StableId&,const StableId&)const override{return false;}std::optional<Integer> authority_epoch(const StableId&)const override{return {};}
 Outcome<AuthorityProof> authorize(const ActingAuthority&,const StableId&,const ScopeRef&,Integer)const override{return {false,{},common_failure("Denied").error};}
 std::optional<OrganizationMemberView> member_view(const StableId&,const StableId&)const override{return {};}
};
PrivateShopResponsibilitySourceContext source(Fixture& f){return {f.common,f.economy,f.economic_catalog,f.state,f.catalog,nullptr};}
StableId fact(Fixture& f,const char* prefix,const char* kind,const char* domain){auto id=f.common.next_id(prefix);check(id.ok,"allocate source ID");check(f.common.append_fact({id.value,kind,domain}).ok,"append original source header");return id.value;}
void original_lease(){Fixture f;auto opened=open_private_shop(f.common,f.economy,f.state,f.context(),f.meeting(),f.quote());check(opened.ok,"original lease writer");NoPublicAuthority public_read;auto x=source(f);const auto before=encode_common_state(f.common.state());check(validate_local_economy(f.common,f.economy,f.economic_catalog,public_read,nullptr,nullptr,nullptr,nullptr,&x).ok,"actual private lease admitted without public grant");check(!validate_local_economy(f.common,f.economy,f.economic_catalog,public_read).ok,"old no-source overload still rejects");check(compare_boundary(before,encode_common_state(f.common.state())).exact(),"LE proof remains read only");auto* rent=f.economy.obligations.find(opened.value.rent_obligation_id);auto saved=*rent;rent->source_wallet_or_inventory="owner.wallet";check(!read_private_shop_economy_source_ids(x).ok,"cannot redirect frozen shop payer");*rent=saved;rent->active=true;check(!read_private_shop_economy_source_ids(x).ok,"private contract cannot become automatic institution debt");*rent=saved;auto erased=f.state.shops;f.state.shops.erase(opened.value.shop_id);check(!read_private_shop_economy_source_ids(x).ok,"missing original opening cannot be exempt");f.state.shops=erased;}
// 原服务记录使用实际三头分配和等额付款，故同 tick 补尾不需要扩大普通应付唯一性。
void original_fraction(){Fixture f;auto opened=open_private_shop(f.common,f.economy,f.state,f.context(),f.meeting(),f.quote());check(opened.ok,"open before staff source");const auto shop=*f.state.shops.find(opened.value.shop_id);f.economic_catalog.rates.insert("staff.rate",{"staff.rate",3,2,false});PrivateShopStaffPolicy policy;policy.id="worker.policy";policy.premises_id="stall";policy.worker_actor_id="lessor";policy.wage_rate_profile="staff.rate";policy.service_ticks=60;policy.service_item_id="grain";f.catalog.staff.policies.insert(policy.id,policy);
 PrivateShopStaffContract contract;contract.id=fact(f,"private_shop_staff","private_shop_staff_accepted",private_shop_module);contract.obligation_id=f.common.next_id("private_shop_wage").value;contract.terms={policy.id,shop.id,"owner","lessor",shop.wallet_id,"lessor.wallet","staff.rate",3,2,60,"grain"};contract.through_tick=60;f.state.staff.contracts.insert(contract.id,contract);RecurringObligation wage;wage.id=contract.obligation_id;wage.principal={SubjectKind::actor,"owner"};wage.beneficiary={SubjectKind::actor,"lessor"};wage.kind=ObligationKind::wage;wage.source_wallet_or_inventory=shop.wallet_id;wage.destination="lessor.wallet";wage.rate_profile="staff.rate";wage.authority_ref=contract.id;wage.period_ticks=1;wage.next_due_tick=1;wage.active=false;f.economy.obligations.insert(wage.id,wage);f.economy.obligation_remainders.insert(wage.id,0);
 auto pay=[&](const StableId& obligation,Integer tick,Integer amount,const StableId& authority){auto d=fact(f,"local_due",obligation==wage.id?"wage_due":"contract_payment_due","local_economy"),p=fact(f,"local_payment","obligation_payment","local_economy");f.economy.arrears.insert(d,{d,obligation,tick,amount,amount});f.economy.payments.insert(p,{p,d,obligation,shop.wallet_id,"lessor.wallet",tick,tick,amount,authority});f.economy.obligations.find(obligation)->last_receipt_id=p;check(f.common.apply_resources({{WalletDelta{shop.wallet_id,-amount,true},WalletDelta{"lessor.wallet",amount,true}}, {}}).ok,"actual original equal wallet legs");return std::make_pair(d,p);};
 PrivateShopOperation operation;operation.id=fact(f,"action","private_shop_operating_started",private_shop_module);operation.shop_id=shop.id;operation.actor_id="lessor";operation.item_id="grain";operation.staff_contract_id=contract.id;auto rent=pay(shop.rent_obligation_id,0,2,shop.id);operation.rent_arrear_id=rent.first;operation.rent_payment_id=rent.second;operation.attendance_ticks={1};f.state.operations.insert(operation.id,operation);
 auto first=fact(f,"private_shop_staff_service","private_shop_staff_served",private_shop_module);auto a=pay(wage.id,1,1,contract.id);f.state.staff.services.insert(first,{first,contract.id,operation.id,a.first,a.second,1,1,1,0,1,false});auto fraction=fact(f,"private_shop_staff_service","private_shop_staff_served",private_shop_module);auto b=pay(wage.id,1,1,contract.id);f.state.staff.services.insert(fraction,{fraction,contract.id,operation.id,b.first,b.second,1,1,1,1,0,true});auto end=fact(f,"private_shop_day","private_shop_operating_interrupted",private_shop_module);PrivateShopDayResult result;result.id=end;result.operation_id=operation.id;result.tick=1;result.shop_id=shop.id;result.actor_id="lessor";result.reason="cancelled";f.state.operating_results.insert(end,result);f.state.operations.find(operation.id)->result_fact_id=end;f.common.state().identity.tick=1;f.economy.last_step_tick=f.state.last_step_tick=1;
 auto x=source(f);NoPublicAuthority public_read;auto ids=read_private_shop_economy_source_ids(x);check(ids.ok&&ids.value.obligation_ids.size()==2&&ids.value.fractional_arrear_ids==std::vector<StableId>{b.first},"only exact closing fraction receives duplicate-period exemption");check(validate_local_economy(f.common,f.economy,f.economic_catalog,public_read,nullptr,nullptr,nullptr,nullptr,&x).ok,"same tick normal and fractional original wages pass LE");auto* paid=f.economy.payments.find(b.second);++paid->amount;check(!read_private_shop_economy_source_ids(x).ok,"source amount cannot drift");--paid->amount;auto* service=f.state.staff.services.find(fraction);service->closing_fraction=false;check(!read_private_shop_economy_source_ids(x).ok,"normal service cannot impersonate fractional source");service->closing_fraction=true;f.state.staff.services.erase(first);check(!read_private_shop_economy_source_ids(x).ok,"missing first service cannot leave self-consistent tail");}
}
int main(){try{original_lease();original_fraction();std::cout<<checks<<"/0 Shop1 original LE source checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
